const event = $input.first().json.body ?? $input.first().json;
const record = event.record;
if (event.type !== 'INSERT' || event.table !== 'submissions' || !record) {
  throw new Error('Expected a Supabase INSERT event for public.submissions.');
}
if (record.content_type !== 'text') {
  return [];
}
if (!record.id || typeof record.content_text !== 'string' || !Array.isArray(record.rules_snapshot)) {
  throw new Error('The submission is missing its id, content, or saved rulebook snapshot.');
}
return [{ json: {
  submission_id: record.id,
  content_text: record.content_text,
  rules_snapshot: record.rules_snapshot
} }];

const response = $input.first().json;
const submissionId = $('Validate submission').first().json.submission_id;
let result;
let analysisStatus = 'completed';
let publishingStatus = '';
let score = null;
let violations = [];
let recommendations = [];
try {
  const content = response.choices?.[0]?.message?.content;
  if (typeof content !== 'string') throw new Error('OpenAI did not return an analysis.');
  result = JSON.parse(content);
  const validStatuses = ['Ready to publish', 'Changes required', 'Escalation recommended', 'Needs human review'];
  if (!validStatuses.includes(result.publishing_status)) throw new Error('OpenAI returned an unknown publishing status.');
  if (result.compliance_score !== null && (!Number.isInteger(result.compliance_score) || result.compliance_score < 0 || result.compliance_score > 100)) throw new Error('OpenAI returned an invalid compliance score.');
  if (!Array.isArray(result.violations) || !Array.isArray(result.recommendations)) throw new Error('OpenAI returned an invalid analysis shape.');
  publishingStatus = result.publishing_status;
  score = result.compliance_score;
  violations = result.violations;
  recommendations = result.recommendations;
} catch (error) {
  analysisStatus = 'failed';
  publishingStatus = 'Analysis failed';
  recommendations = ['The n8n/OpenAI workflow could not complete this analysis. Please raise a ticket for manual review.'];
}
return [{ json: {
  submission_id: submissionId,
  analysis_status: analysisStatus,
  publishing_status: publishingStatus,
  compliance_score: score,
  violations,
  recommendations
} }];
